package com.example.leavemanagement.balance.api;
import com.example.leavemanagement.balance.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/admin/employees/{employeeId}/leave-balances") public class AdminBalanceController {private final BalanceAllocationService allocation;private final BalanceAdjustmentService adjustment;public AdminBalanceController(BalanceAllocationService a,BalanceAdjustmentService b){allocation=a;adjustment=b;} @GetMapping public List<LeaveBalanceService.BalanceView> list(@PathVariable UUID employeeId){return allocation.list(employeeId);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public LeaveBalanceService.BalanceView allocate(@PathVariable UUID employeeId,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody Allocation c){return allocation.allocate(employeeId,new BalanceAllocationService.Command(c.leaveTypeId(),c.periodStart(),c.periodEnd(),c.allocatedDays(),c.reason()),key);} @PostMapping("/{balanceId}/adjustments") public LeaveBalanceService.BalanceView adjust(@PathVariable UUID balanceId,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody Adjustment c){return adjustment.adjust(balanceId,new BalanceAdjustmentService.Command(c.adjustmentDays(),c.reason(),c.expectedVersion()),key);} public record Allocation(@NotNull UUID leaveTypeId,@NotNull LocalDate periodStart,@NotNull LocalDate periodEnd,@DecimalMin("0")double allocatedDays,@NotBlank String reason){} public record Adjustment(@NotNull Double adjustmentDays,@NotBlank String reason,@NotNull @Min(0)Long expectedVersion){} }
